from pathlib import Path
import re,json
b=Path('EsportsClash.Web/src')
def change(name,fn):
 p=b/name;p.write_text(fn(p.read_text(encoding='utf-8')),encoding='utf-8')
for p in (b/'fps').glob('*.ts'):
 s=p.read_text(encoding='utf-8').replace('opportunities:new Set(),','');s=re.sub(r'^export type FpsTacticalOpportunity =.*?\n','',s,flags=re.M).replace('opportunities:ReadonlySet<FpsTacticalOpportunity>;','');p.write_text(s,encoding='utf-8')
change('fps/fpsIdentity.ts',lambda s:s.replace('type FpsAssignments,','type FpsAssignments, type FpsPosition,').replace('Partial<Record<FpsPrimaryRole,number>>','Partial<Record<FpsPosition,number>>'))
change('components/FpsTacticalSystemEditor.tsx',lambda s:s.replace("import {FPS_ROLES} from '../fps/fpsRoleFit';\n",'').replace('type FpsPrimaryRole','type FpsPosition').replace("FPS_ROLES.map(role=>{const value=report.role_familiarity?.[role.id as FpsPrimaryRole]??0;return role.name+': '","[...FPS_T_POSITIONS,...FPS_CT_POSITIONS].map(position=>{const value=report.role_familiarity?.[position]??0;return FPS_POSITION_LABELS[position]+': '"))
change('fpsReference.test.mjs',lambda s:re.sub(r"import \{FPS_ROLES,rankFpsRoleFits\}.*\n",'',s))
change('fps/fpsReference.ts',lambda s:s.replace("import {FPS_ROLES} from './fpsRoleFit.ts';\n",'').replace("rifling:'Aim and weapon mechanics influence shots and entry suitability.'","rifling:'Rifle, pistol and SMG gunfight execution.'").replace("entry:'Teamwork and trading help identify close follow-up and support assignments.'","entry:'Breaking chokes, first-contact execution and creating space.'").replace("positioning:'Game sense contributes to calls, preparation and utility-oriented role fits.'","positioning:'Map awareness, rotations, angles and survival execution.'").replace("shotcalling:'Shotcalling helps select the in-game leader from the full lineup.'","shotcalling:'Execution quality of planning, economy calls and counter-strategies; the IGL assignment is chosen separately.'").replace("sniping:'Clutch skill contributes to scouting for pressure roles and late-round specialties.'","sniping:'Sniper rifle execution, including AWP and Scout engagements.'").replace("utility:'Stamina limits round-to-round fatigue and helps recover composure.'","utility:'Grenade deployment accuracy and timing within fixed physical rules.'"))
p=b/'fps/fpsRoleFit.ts';s=p.read_text(encoding='utf-8');i=s.index('export function fpsRoleFit(');p.write_text("export type FpsSkillKey=keyof import('../types.ts').PlayerAttributes;\n/** Execution strength only; this never derives a role or a behavioral identity. */\n"+s[i:],encoding='utf-8')
change('fps/fpsSkillProfile.ts',lambda s:s[:s.index('export function fpsDetailedRoleFit(')].replace("import type {FpsPrimaryRole} from './fpsIdentity.ts';\n",''))
change('fps/fpsLiveSimulation.ts',lambda s:s.replace('fpsDetailedRoleFit, ',''))
change('components/GameGuide.tsx',lambda s:s.replace('Opening roles include entry, trade fragger, utility support and defender anchor. The IGL is a separate responsibility and can hold any role. Personality preferences can shift a close assignment; skills remain the main input.','Each lineup assigns a T IGL, Entry, Support, Lurker and Flex, plus a CT IGL, Rotator, A Anchor, B Anchor and Flex. Both sides lock at allocation. Personality shapes how players approach their responsibilities; six attributes govern execution.').replace('This first playable uses an abstract tactical simulation; it does not yet model continuous first-person movement or every weapon interaction.','Recorded tactical matches and live 3D exhibitions share the player architecture. The live exhibition resolves continuous movement, vision and physical weapon interactions.'))
change('components/FpsSkillEditor.tsx',lambda s:s.replace("data.format!=='hexatrick-fps-skill-lab-v2'","!['hexatrick-fps-skill-lab-v1','hexatrick-fps-skill-lab-v2'].includes(data.format)").replace('validateFpsSkillProfile(data.profiles[p.id],p.id)','migrateFpsSkillProfile(data.profiles[p.id],p.id)'))
change('types.ts',lambda s:s.replace("| 'utility' | 'utility'","| 'utility'").replace('Boosts IQ & Leadership training speed','Boosts Positioning & Shotcalling training speed').replace('Boosts Mechanics & Trading training speed','Boosts Rifling, Sniping & Entry training speed').replace('Boosts Clutch, Stamina & Flexibility training speed','Supports physical recovery and utility practice'))
change('marketBatchEngine.ts',lambda s:s.replace("focus === 'utility' || focus === 'utility'","focus === 'utility'").replace('stats.utility * 0.1 + stats.utility * 0.1','stats.utility * 0.1 + stats.shotcalling * 0.1').replace("| 'utility' | 'utility'","| 'utility'"))
# Keep the complete 18-profile tendency descriptions with the same versioned identity metadata.
p=Path('EsportsClash.Api/resources/fps-player-architecture-v4.json');c=json.loads(p.read_text(encoding='utf-8'))
descriptions=['Patiently exploits openings but can react prematurely.','Seeks carefully selected personal duels but can miss timing windows.','Adjusts routes for favorable personal opportunities but can surrender initiative.','Reacts rapidly to teammates’ needs but may rely on others for initiative.','Follows deliberate team plans but can become predictable.','Maintains team structure while adjusting responsibilities but can be overly cautious.','Makes spontaneous independent plays but can disrupt coordination.','Plans individual plays carefully but can overprepare.','Changes approach to find personal impact but can disrupt team timing.','Responds quickly to team-created opportunities but can commit prematurely.','Executes structured team decisions but can hesitate to improvise.','Adjusts responsibilities to help the team but can over-adjust.','Frequently seeks direct combat but risks overextension.','Engineers planned aggressive engagements but can become predictable.','Hunts engagements dynamically but can lose focus on team objectives.','Creates space for teammates but risks advancing beyond support.','Executes coordinated aggressive plans but can overcommit.','Creates proactive pressure while adapting but can disrupt synchronization.']
for profile,description in zip(c['profiles'],descriptions):profile['tendency']=description
p.write_bytes((json.dumps(c,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
change('fps/fpsPlayerArchitecture.ts',lambda s:s.replace("export const personalityLabel=(value:string)=>value.toLowerCase()", "export const personalityLabel=(value:string)=>value==='ICE_COLD'?'Ice-Cold':value==='TEAM_FIRST'?'Team-First':value.toLowerCase()"))
change('components/FpsIdentityMarks.tsx',lambda s:s.replace('naturalFpsIdentity,observedFpsIdentity','FPS_BASE_BEHAVIORAL_PROFILES,fpsBaseProfileId,naturalFpsIdentity,observedFpsIdentity').replace('title="Natural preferences; mechanical proficiency is separate"','title={FPS_BASE_BEHAVIORAL_PROFILES[fpsBaseProfileId(p)-1].tendency}'))
change('fps/fpsReference.ts',lambda s:s.replace('FPS_POSITION_LABELS,personalityLabel','FPS_POSITION_LABELS,FPS_BASE_BEHAVIORAL_PROFILES,fpsBaseProfileId,personalityLabel').replace("body:['Natural behavioral preferences", "body:[FPS_BASE_BEHAVIORAL_PROFILES[fpsBaseProfileId(p)-1].tendency,'Natural behavioral preferences"))
