p=Path('EsportsClash.Api/app/Console/Commands/FpsIdentityRelease.php');s=p.read_text(encoding='utf-8').replace('status, prepare, enable or disable','status or prepare');a=s.index("        } elseif(in_array($action,['enable','disable'],true))");z=s.index("        } elseif($action!=='status')",a);s=s[:a]+s[z:];p.write_text(s,encoding='utf-8')
